const startCapture = async ({
  region,
  fps,
  workDir,
}: {
  region: Region;
  fps: number;
  workDir: string;
}): Promise<Capture> => {
  const rawPath = path.join(workDir, "capture.mkv");
  const child = spawn(
    "ffmpeg",
    [
      "-hide_banner",
      "-loglevel",
      "error",
      "-f",
      "x11grab",
      "-framerate",
      String(fps),
      "-video_size",
      `${region.width}x${region.height}`,
      "-draw_mouse",
      "0",
      "-i",
      `:0.0+${region.x},${region.y}`,
      "-c:v",
